public static double calculateAverageBalance(List<Double> closingBalances) {
    if (closingBalances == null) {
        throw new IllegalArgumentException("The list of closing balances cannot be null.");
    }
    if (closingBalances.size() != 12) {
        throw new IllegalArgumentException("The list of closing balances must contain exactly 12 elements.");
    }

    double sum = 0.0;
    for (Double balance : closingBalances) {
        if (balance == null) {
            throw new IllegalArgumentException("A balance in the list cannot be null.");
        }
        sum += balance;
    }

    return sum / 12.0;
}

