    if (N <= 0) {
        throw new IllegalArgumentException("Number of people must be greater than zero.");
    }
    // The time needed to reverse the seating order is (N - 1) minutes
    // This is because each person needs to move once, except the first person who doesn't move
    return N - 1;
}

