public static int calculateTimeNeeded(int N) {
    if (N <= 0) {
        throw new IllegalArgumentException("Number of people must be greater than zero.");
    }
    // The time needed is calculated as (N/2) * 2 which simplifies to N-1 for odd N and N for even N.
    // Observing the pattern, the time needed is actually N-1 for any N >= 2.
    // For N = 1, no time is needed as there's only one person.
    return N > 1 ? N - 1 : 0;
}

