public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (int length = 1; length <= strings.get(0).length(); length++) {
        for (int i = 0; i <= strings.get(0).length() - length; i++) {
            String substring = strings.get(0).substring(i, i + length);
            String inverseSubstring = new StringBuilder(substring).reverse().toString();

            boolean allContain = true;
            for (String str : strings) {
                if (!str.contains(substring) && !str.contains(inverseSubstring)) {
                    allContain = false;
                    break;
                }
            }

            if (allContain) {
                maxLength = length;
            }
        }
    }

    return maxLength;
}

