    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (int i = 0; i < strings.size(); i++) {
        for (int j = i + 1; j < strings.size(); j++) {
            String str1 = strings.get(i);
            String str2 = strings.get(j);

            int length = Math.min(str1.length(), str2.length());
            for (int len = length; len > 0; len--) {
                for (int start = 0; start <= length - len; start++) {
                    String sub = str1.substring(start, start + len);
                    String revSub = new StringBuilder(sub).reverse().toString();

                    if ((str2.contains(sub) || str2.contains(revSub)) &&
                        strings.stream().allMatch(s -> s.contains(sub) || s.contains(revSub))) {
                        maxLength = Math.max(maxLength, len);
                    }
                }
            }
        }
    }

    return maxLength;
}

