public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    // The formula to calculate the maximum number of regions is 2 + 3 * N * (N + 1) / 2
    // This formula is derived from the fact that each new triangle can intersect with all previous ones
    // creating new regions.
    return 2 + 3 * N * (N + 1) / 2;
}

