public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    // Base case: with 0 triangles, the plane is undivided, so 1 region.
    if (N == 0) {
        return 1;
    }
    // The formula to calculate the maximum number of regions created by N triangles
    // is derived from the fact that each new triangle can intersect all previous
    // triangles in at most 6 new points, creating 7 new regions.
    // regions(N) = regions(N-1) + 7*(N-1) + 1
    // Simplifying, we get regions(N) = 7*N - N*(N-1)/2
    return 7 * N - N * (N - 1) / 2;
}

