public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }
    int n = arr.length;
    int toRemove = n / 20; // 5% of the elements to remove from each end

    if (toRemove == 0) {
        // If 5% is less than 1, we cannot remove any elements
        // In this case, we return the mean of the entire array
        double sum = 0;
        for (int num : arr) {
            sum += num;
        }
        return sum / n;
    }

    // Sort the array
    java.util.Arrays.sort(arr);

    // Calculate the sum of the elements excluding the smallest and largest 5%
    double sum = 0;
    for (int i = toRemove; i < n - toRemove; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the remaining elements
    return sum / (n - 2 * toRemove);
}

