public int minInsertions(String s) {
    int openCount = 0; // To count the number of unmatched '('
    int insertions = 0; // To count the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char currentChar = s.charAt(i);

        if (currentChar == '(') {
            openCount++;
        } else { // currentChar == ')'
            if (openCount > 0) {
                openCount--;
            } else {
                // If there's no matching '(', we need to insert one
                insertions++;
            }
            // Check if we need to insert a ')' to balance a single ')'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')' as it is balanced
            } else {
                insertions++; // Insert a ')' to balance the current ')'
            }
        }
