public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int a = 1, b = 1;
    while (b <= k) {
        int temp = a;
        a = b;
        b = temp + b;
    }

    int count = 0;
    while (k > 0) {
        int temp = a;
        a = b;
        b = temp;
        if (a <= k) {
            k -= a;
            count++;
        }
    }

    return count;
}

