public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    // Generate Fibonacci numbers up to k
    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    while (b <= k) {
        fibs.add(b);
        int next = a + b;
        a = b;
        b = next;
    }

    // Use greedy approach to find the minimum number of Fibonacci numbers
    int count = 0;
    int index = fibs.size() - 1;
    while (k > 0) {
        count += k / fibs.get(index);
        k %= fibs.get(index);
        index--;
    }

    return count;
}

