public int minOperations(String[] logs) {
    if (logs == null) {
        throw new IllegalArgumentException("Input logs array cannot be null");
    }

    int steps = 0;
    for (String log : logs) {
        if (log == null || log.isEmpty()) {
            continue; // Skip null or empty log entries
        } else if (log.equals("../")) {
            steps = Math.max(0, steps - 1); // Move up one directory if not already at root
        } else if (!log.equals("./")) {
            steps++; // Move into a subdirectory
        }
    }
    return steps;
}

