public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }

    int count = 0;
    for (int m = 1; m <= n; m *= 10) {
        int a = n / m;
        int b = n % m;
        count += (a / 10) * m + Math.min(Math.max(a % 10 - 1, 0) * m, b + 1);
    }
    return count;
}

