public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Directions for horizontal, vertical, diagonal, and anti-diagonal
    int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                for (int[] direction : directions) {
                    int x = i;
                    int y = j;
                    int currentLength = 0;

                    while (x >= 0 && x < m && y >= 0 && y < n && mat[x][y] == 1) {
                        currentLength++;
                        x += direction[0];
                        y += direction[1];
                    }

                    maxLength = Math.max(maxLength, currentLength);
                }
            }
        }
    }

    return maxLength;
}

