public static int findSmallestInteger(int n) {
    String numStr = Integer.toString(n);
    char[] digits = numStr.toCharArray();
    int length = digits.length;

    // Find the rightmost digit that is smaller than the digit next to it
    int i = length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit on the right side of (i) which is larger than digits[i]
    int j = length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits after (i) to get the smallest possible number
    j = length - 1;
    while (i < j) {
        temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;
        i++;
        j--;
    }

    // Convert the array of digits back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case of overflow
    }
}

